Implement Calculator in src/calculator.py.

class Calculator:
    def __init__(self):
        self.vars: dict[str, float] = {}

    def eval(self, expr: str) -> float:
        expr = expr.strip()
        # Check for assignment: 'name = expr'
        if '=' in expr:
            name, _, rhs = expr.partition('=')
            name = name.strip()
            value = self._evaluate(rhs.strip())
            self.vars[name] = value
            return value
        return self._evaluate(expr)

    def _evaluate(self, expr: str) -> float:
        # Replace variable names with their values
        import re
        def replace_var(m):
            name = m.group(0)
            if name in self.vars:
                return str(self.vars[name])
            return name
        expr = re.sub(r'[a-zA-Z_][a-zA-Z0-9_]*', replace_var, expr)
        return float(eval(expr))  # safe for controlled input

